import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const moduleRoot = path.resolve(scriptDir, '..', 'core');
const outputDir = path.resolve(scriptDir, '..', 'browser');
const outputPath = path.join(outputDir, 'open-vocal-biomarkers.mjs');
const moduleNames = [
  'constants',
  'utils',
  'audio',
  'acoustic_features',
  'quality',
  'marker_scoring',
  'condition_flags',
  'analyzer',
  'report',
  'engine',
];

function factorySource(name, source) {
  return `${JSON.stringify(`./${name}`)}: function(module, exports, require) {\n${source}\n}`;
}

const factories = [];
for (const name of moduleNames) {
  const source = await readFile(path.join(moduleRoot, `${name}.js`), 'utf8');
  factories.push(factorySource(name, source));
}

const generated = `/*
 * AUTO-GENERATED by Audio_detection/scripts/build-browser-bundle.mjs.
 * Source: Audio_detection/core/*.js (MIT). Do not edit this file directly.
 */
const __factories = {
${factories.join(',\n')}
};
const __cache = new Map();
function __normalize(id) {
  return String(id).replace(/\\.js$/, '');
}
function __require(id) {
  const key = __normalize(id);
  if (__cache.has(key)) return __cache.get(key).exports;
  const factory = __factories[key];
  if (!factory) throw new Error('Unknown bundled module: ' + key);
  const module = { exports: {} };
  __cache.set(key, module);
  factory(module, module.exports, __require);
  return module.exports;
}

const core = __require('./engine');
export const MODULE_VERSION = core.MODULE_VERSION;
export const DEFAULT_CONFIG = core.DEFAULT_CONFIG;
export const mergeConfig = core.mergeConfig;
export const analyzePcmSamples = core.analyzePcmSamples;
export const analyzeAudioArrayBufferBrowser = core.analyzeAudioArrayBufferBrowser;
export const analyzeAudioFileBrowser = core.analyzeAudioFileBrowser;
export const analyzeAudioFile = core.analyzeAudioFile;
export const getCapabilities = core.getCapabilities;
export const toJsonReport = core.toJsonReport;
export const fromJsonReport = core.fromJsonReport;
export const analyzePcmSamplesJson = core.analyzePcmSamplesJson;
export const analyzeAudioArrayBufferBrowserJson = core.analyzeAudioArrayBufferBrowserJson;
export const analyzeAudioFileBrowserJson = core.analyzeAudioFileBrowserJson;
export const analyzeAudioFileJson = core.analyzeAudioFileJson;
export default core;
`;

await mkdir(outputDir, { recursive: true });
await writeFile(outputPath, generated, 'utf8');
console.log(outputPath);
